function quickSort(a, low = 0, high = a.length - 1) {
  if (low >= high) return a;         // 0 or 1 elements: already sorted

  const p = partition(a, low, high);
  quickSort(a, low, p - 1);          // p is excluded: it is already final
  quickSort(a, p + 1, high);
  return a;
}

function partition(a, low, high) {
  const pivot = a[high];
  let i = low - 1;                   // end of the "smaller" region, empty so far

  for (let j = low; j < high; j++) {
    if (a[j] < pivot) {
      i++;
      [a[i], a[j]] = [a[j], a[i]];   // grow the region and move a[j] into it
    }
  }

  [a[i + 1], a[high]] = [a[high], a[i + 1]];   // pivot onto the boundary
  return i + 1;
}

