#include <vector>
#include <utility>

int partition(std::vector<int>& a, int low, int high) {
    int pivot = a[high];
    int i = low - 1;                 // end of the "smaller" region, empty so far

    for (int j = low; j < high; j++) {
        if (a[j] < pivot) std::swap(a[++i], a[j]);   // grow and move in
    }

    std::swap(a[i + 1], a[high]);    // pivot onto the boundary
    return i + 1;
}

void quickSort(std::vector<int>& a, int low, int high) {
    if (low >= high) return;         // 0 or 1 elements: already sorted
    int p = partition(a, low, high);
    quickSort(a, low, p - 1);        // p excluded: already final
    quickSort(a, p + 1, high);
}
